{"file_path":"tests/test_metrics.py","content":"from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "large": [{"converted": True}, {"converted": False}, {"converted": False}],
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window_uses_exact_last_days():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2], 5) == 3
    assert conversions_in_window([1, 2], 0) == 0


def test_parse_session_log_values_and_skipped_lines():
    lines = ["  # comment", "", " x1, 3, 1 ", "x2,4,0", "x3,5,"]
    assert parse_session_log(lines) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_errors_include_original_line_number():
    try:
        parse_session_log(["# skipped", "x,not-a-day,1"])
    except ValueError as error:
        assert "line 2" in str(error)
    else:
        raise AssertionError("expected ValueError")

    try:
        parse_session_log(["x,1"])
    except ValueError as error:
        assert "line 1" in str(error)
    else:
        raise AssertionError("expected ValueError")


def test_dedupe_sessions_keeps_last_record_for_duplicate_id():
    first = {"id": "same", "day": 1, "converted": True}
    replacement = {"id": "same", "day": 3, "converted": False}
    other = {"id": "other", "day": 2, "converted": True}
    assert dedupe_sessions([first, other, replacement]) == [other, replacement]


def test_daily_conversion_counts_inclusive_range_and_empty_range():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": None},
        {"id": "c", "day": 2, "converted": True},
        {"id": "d", "day": 5, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [1, 1, 0]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_uses_spec_rounding_and_populated_group_count():
    groups = {
        "a": [{"id": "x", "day": 1, "converted": True}],
        "b": [{"id": "y", "day": 2, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}


def test_top_groups_ties_by_name_and_excludes_empty_groups():
    groups = {
        "z": [{"converted": True}],
        "a": [{"converted": True}],
        "empty": [],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    assert conversion_rate_by_group({"z": [], "a": [{"converted": True}]}) == {
        "a": 1.0,
        "z": None,
    }


def test_longest_conversion_streak_requires_positive_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 4]) == 2
    assert longest_conversion_streak([]) == 0
